export class Client {
  constructor(value) {
    this.value = value;
    this.hook = { count: 0 };
  }
}
export function echo(client) { return client; }
export function maybe(client) { return client; }
export function read(client) { return client.value; }
export function touch(client, count) { client.hook.count = count; }
export function put(options, key, value) { options[key] = value; return options; }
export function lookup(options, key) { return options[key]; }
export function plugin(client, options) {
  return { retry: (candidate, count) => { client.hook.count = count; options.last = candidate; return candidate; } };
}
plugin.VERSION = "1";
export function array(values) { return values; }
export function tuple(values) { return values; }
export class Envelope { constructor(value) { this.value = value; } }
export function envelope(value) { return value; }
export class Derived extends Client { constructor(value) { super(value); this.extra = { value }; } }
export function derivedValue(value) { return value.extra.value; }
